+++ b/source/core/utils/options-to-url.ts
@@ -44,26 +44,31 @@ export default function optionsToUrl(origin: string, options: URLOptions): URL {
 			throw new TypeError('No URL protocol specified');
 		}

-		origin = `${options.protocol}//${options.hostname ?? options.host ?? ''}`;
+		const host = options.hostname ?? options.host;
+		if (!host) {
+			throw new TypeError('No URL host specified');
+		}
+
+		origin = `${options.protocol}//${host}`;
 	}

 	const url = new URL(origin);
+	const values: Partial<Record<typeof keys[number], string | number>> = {...options};

 	if (options.path) {
 		const searchIndex = options.path.indexOf('?');
 		if (searchIndex === -1) {
-			options.pathname = options.path;
+			values.pathname = options.path;
 		} else {
-			options.pathname = options.path.slice(0, searchIndex);
-			options.search = options.path.slice(searchIndex + 1);
+			values.pathname = options.path.slice(0, searchIndex);
+			values.search = options.path.slice(searchIndex + 1);
 		}
-
-		delete options.path;
 	}

 	for (const key of keys) {
-		if (options[key]) {
-			url[key] = options[key].toString();
+		const value = values[key];
+		if (value) {
+			url[key] = value.toString();
 		}
 	}

diff --git a/source/endpoint-preview.ts b/source/endpoint-preview.ts
