index 0000000..147f9ed
--- /dev/null
+++ b/source/endpoint-preview.ts
@@ -0,0 +1,20 @@
+import optionsToUrl, {type URLOptions} from './core/utils/options-to-url.js';
+
+export type EndpointPreviewChanges = Omit<URLOptions, 'href'>;
+
+/**
+Preview the final URL of a request built from `origin` and the given URL option `changes`, without modifying `changes`.
+
+`origin` may be an empty string when `changes` provides `protocol` and `hostname` or `host`.
+
+@throws {TypeError} When `path` is combined with `pathname`, `search` or `searchParams`, or `search` is combined with `searchParams`.
+
+@example
+```
+endpointPreview('https://example.com', {path: '/users?page=2', port: 8080});
+//=> 'https://example.com:8080/users?page=2'
+```
+*/
+export function endpointPreview(origin: string, changes: Readonly<EndpointPreviewChanges>): string {
+	return optionsToUrl(origin, changes).toString();
+}
diff --git a/test/endpoint-preview.ts b/test/endpoint-preview.ts
new file mode 100644
index 0000000..48c0847
--- /dev/null
+++ b/test/endpoint-preview.ts
@@ -0,0 +1,47 @@
+import test from 'ava';
+import {endpointPreview} from '../source/endpoint-preview.js';
+
+test('applies protocol, hostname, port, pathname and search to origin', t => {
+	t.is(endpointPreview('https://example.com/ignored?x=1', {
+		protocol: 'http:',
+		hostname: 'localhost',
+		port: 8080,
+		pathname: '/api',
+		search: '?a=1',
+	}), 'http://localhost:8080/api?a=1');
+});
+
+test('applies host including port', t => {
+	t.is(endpointPreview('https://example.com', {host: 'got.test:3000'}), 'https://got.test:3000/');
+});
+
+test('splits legacy `path` into pathname and search', t => {
+	t.is(endpointPreview('https://example.com', {path: '/users?page=2'}), 'https://example.com/users?page=2');
+	t.is(endpointPreview('https://example.com/?old=1', {path: '/users'}), 'https://example.com/users?old=1');
+});
+
+test('builds the URL from changes when origin is empty', t => {
+	t.is(endpointPreview('', {protocol: 'https:', hostname: 'example.com', path: '/a?b=c'}), 'https://example.com/a?b=c');
+	t.is(endpointPreview('', {protocol: 'http:', host: 'example.com:81'}), 'http://example.com:81/');
+});
+
+test('throws when origin is empty and protocol or host is missing', t => {
+	t.throws(() => endpointPreview('', {hostname: 'example.com'}), {instanceOf: TypeError, message: 'No URL protocol specified'});
+	t.throws(() => endpointPreview('', {protocol: 'https:'}), {instanceOf: TypeError, message: 'No URL host specified'});
+});
+
+test('does not modify changes', t => {
+	const changes = {path: '/users?page=2', port: 8080};
+	const snapshot = structuredClone(changes);
+
+	endpointPreview('https://example.com', changes);
+
+	t.deepEqual(changes, snapshot);
+});
+
+test('rejects ambiguous combinations', t => {
+	t.throws(() => endpointPreview('https://example.com', {path: '/a', pathname: '/b'}), {instanceOf: TypeError, message: 'Parameters `path` and `pathname` are mutually exclusive.'});
+	t.throws(() => endpointPreview('https://example.com', {path: '/a', search: '?b=c'}), {instanceOf: TypeError, message: 'Parameters `path` and `search` are mutually exclusive.'});
+	t.throws(() => endpointPreview('https://example.com', {path: '/a', searchParams: {b: 'c'}}), {instanceOf: TypeError, message: 'Parameters `path` and `searchParams` are mutually exclusive.'});
+	t.throws(() => endpointPreview('https://example.com', {search: '?a=1', searchParams: {b: 'c'}}), {instanceOf: TypeError, message: 'Parameters `search` and `searchParams` are mutually exclusive.'});
+});
